    vx = vel.x
    vy = vel.y
    target_y = 11.7
    dead_zone_threshold = 1.5  # Increased to avoid suppression during critical phases

    # Check if we are at the apex or near vertical fall
    if abs(vx) < 1.35 and abs(vy) < 1.0:
