        wind_dir = 1  # Wind is blowing to the right
    elif vx < 0:
        wind_dir = -1  # Wind is blowing to the left
    else:
        wind_dir = 0  # No wind or wind is negligible

    # Apply horizontal force in the direction that counteracts wind and moves toward the pivot
