        desired_fx = -42.0  # Opposite of wind direction
    elif wind_dir == -1:
        desired_fx = 42.0  # Opposite of wind direction
    else:
        # Default: move toward the pivot
        desired_fx = 42.0 if pos.x < 10 else -42.0

    # Apply vertical force to help reach the target
    if pos.y < target_y:
        desired_fy = 42.0
    else:
        desired_fy = -42.0

    # Apply forces only if horizontal speed is above the dead zone threshold
    if abs(vx) > dead_zone_threshold:
        sandbox.apply_force_to_seat(desired_fx, desired_fy)
    else:
        # Apply only vertical force when horizontal speed is low
        sandbox.apply_force_to_seat(0, desired_fy)

